description:
Design a clock divider circuit that generates a toggling output signal (`clk_out`) at a lower frequency derived from the input clock (`clk`). The circuit counts up to 9999 on each rising edge of the clock, and upon reaching this count, it toggles the output and resets the count back to zero. On reset (`rst_n`), the count and output are initialized to zero. This effectively divides the clock frequency by 20000, creating a slower clock signal from the input.
module top_module(
            clk,
            rst_n,
            clk_out
    );

code:
module top_module(
            clk,
            rst_n,
            clk_out
    );input clk;
input rst_n;
output reg clk_out;

reg [14:0] cnt;


always @(posedge clk or negedge rst_n)
begin
    if(!rst_n)
    begin
        cnt <= 15'b0;
        clk_out <= 1'b0;
    end
    else
    begin
        if(cnt == 9999)
        begin
            clk_out <= ~clk_out;
            cnt <= 15'b0;
        end
        else
        begin
            cnt <= cnt + 15'b1;
        end
    end
end

endmodule

