module top_module(
  input wire start,
  input wire mdc,
  input wire mdio,
  output reg tx_en,
  output reg rx_en,
  output reg [3:0] txd,
  output reg [3:0] rxd
);// State machine states
  localparam IDLE_STATE = 2'd0;
  localparam TX_STATE = 2'd1;
  localparam RX_STATE = 2'd2;

  // Internal state machine signals
  reg [1:0] state = IDLE_STATE;
  reg [4:0] count = 5'd0;

  // Internal signal to hold the data to be transmitted
  reg [3:0] tx_data;

  always @(posedge mdc) begin
    case(state)
      IDLE_STATE: begin
        if(start) begin
          // Transition to the TX_STATE
          state <= TX_STATE;
          count <= 5'd0;
        end
      end

      TX_STATE: begin
        // Transmit the data
        txd <= tx_data;
        rxd <= 4'd0;
        count <= count + 5'd1;

        if(count == 5'd1) begin
          // Deassert the TX_EN signal and transition to the RX_STATE
          tx_en <= 1'b0;
          state <= RX_STATE;
          count <= 5'd0;
        end else begin
          // Assert tx_en during transmission
          tx_en <= 1'b1;
        end
      end

      RX_STATE: begin
        // Receive the data
        txd <= 4'd0;
        rxd <= mdio;
        count <= count + 5'd1;

        if(count == 5'd1) begin
          // Deassert the RX_EN signal and transition back to the TX_STATE
          rx_en <= 1'b0;
          state <= TX_STATE;
          count <= 5'd0;
        end else begin
          // Assert rx_en during reception
          rx_en <= 1'b1;
        end
      end
    endcase
  end

  always @(posedge mdc) begin
    if(state == TX_STATE && count == 5'd0) begin
      // Load the data to be transmitted
      tx_data <= {4{count[3]}};
    end
  end

endmodule

