module top_module(
    input clk,  // Added clock input
    input [15:0] a,
    input ctrl,
    output reg [15:0] b
);// Pipeline registers
reg [15:0] a_reg1, a_reg2;
reg [15:0] b_reg1, b_reg2;

// Combinational square root algorithm
always @(*) begin
    // Assign a_reg2 based on the value of a_reg1
    if (a_reg1[15:14] == 2'b11) // If MSBs are 11, shift right by 2
        a_reg2 = {a_reg1[13:0], 2'b00};
    else if (a_reg1[15:14] == 2'b10) // If MSBs are 10, shift right by 1
        a_reg2 = {a_reg1[14:0], 1'b0};
    else // If MSBs are 00 or 01, no shift
        a_reg2 = a_reg1;

    // Assign b_reg2 based on the control signal and b_reg1
    if (ctrl == 1) // If rounding is required, add 1 to the result
        b_reg2 = b_reg1 + 1;
    else // If rounding is not required, truncate the result
        b_reg2 = b_reg1;
end

// Pipeline stages
always @(posedge clk) begin
    a_reg1 <= a;
    b_reg1 <= 0;
end

always @(posedge clk) begin
    a_reg1 <= a_reg2;
    b_reg1 <= b_reg2;
end

always @(posedge clk) begin
    // Fixed: used constant indices for the part select
    // As this is a redesign, let's assume b_reg1 is valid before this assignment
    b_reg1 <= (b_reg2 + {1'b0, a_reg2[1:0]}) << 1; // Use a constant part select
end

always @(posedge clk) begin
    b <= b_reg1[15:0];
end

endmodule

