description:
Design a 4-bit wide stack that supports push and pop operations with functionality to indicate when the stack is full or empty. The module includes a stack pointer (SP) to track the position of the top element of the stack, and it raises an error signal when a pop operation is attempted on an empty stack or a push operation exceeds the stack capacity. The stack is resettable, allowing all internal states to be cleared, setting the stack to an empty state with a pointer reset. The DataIO port interacts with an external data source, facilitating the transfer of 4-bit data during push and pop operations.
module top_module(DataIO, Reset, Push, Pop, 
              SP, Full, Empty, Err);

code:
module top_module(DataIO, Reset, Push, Pop, 
              SP, Full, Empty, Err);// declare input, output and inout ports
  inout [3:0] DataIO; 
  input Push, Pop, Reset;
  output Full, Empty, Err;
  output [2:0] SP;

  // Declare registers
  reg Full, Empty, Err;
  reg [2:0] SP;
  reg [3:0] Stack [7:0];
  reg [3:0] DataR;

  //Continous assignment of DataIO to DataR register, with delay 0
  wire [3:0]  #(0) DataIO = DataR;

  //Initialize the stack pointer and flags
  initial begin
    SP = 3'b0;
    Full = 0;
    Empty = 1;
    Err = 0;
  end

  always @(posedge Push or posedge Pop or posedge Reset) 
  begin

    if (Push == 1)
    begin
      //WHen the stack is empty
      if (Empty == 1)
      begin
        Stack[SP] = DataIO;
        Empty = 0;
        if (Err == 1)
          Err = 0;
      end
      else if (Full == 1) //When the stack is full
      begin
        Stack[SP] = DataIO;
        Err = 1;
      end
      else
      begin
        SP = SP + 1;
        Stack[SP] = DataIO;
        if (SP == 3'b111)
          Full = 1;
      end
    end


    if (Pop == 1) //if SP indicates the last location but
    begin             // the stack is not empty 
      if ((SP == 3'b000) && (Empty != 1))
      begin
        DataR = Stack[SP];
        Empty = 1;
      end
      else if (Empty == 1) //When the stack is empty
      begin
        DataR = Stack[SP];
        Err = 1;
      end
      else
      begin
        DataR = Stack[SP];
        if (SP != 3'b000)
          SP = SP - 1;
        //if the stack is full
        if (Err == 1)  Err = 0;
        if (Full == 1)  Full = 0;
      end
    end


    if (Reset == 1)
    begin
      DataR = 4'bzzzz;
      SP = 3'b0;
      Full = 0;
      Empty = 1;
      Err = 0;
    end

  end


  always @(negedge Pop)
  begin
    DataR = 4'bzzzz;
  end  


endmodule

