                & ~bits_received[10] 
                & bits_received[9] 
                & ~bits_received[0];

  always @(posedge clk_i) begin
    if (reset_i) begin
      bits_received <= ~0;
      txc_r <= 0;
      ack_o <= 0;
      dat_o <= 0;
    end else begin
      txc_r <= txc_i;
      ack_o <= 0;
      dat_o <= 0;

      if (sample) begin
        bits_received <= {txd_i, bits_received[19:1]};
      end

      if (framed) begin
        bits_received <= ~0;
        if (cyc_i) begin
          ack_o <= 1;
          dat_o <= {bits_received[18:11], bits_received[8:1]};
        end
      end
    end
  end
endmodule

