module ring_counter (
    input clk,
    input reset,
    output reg [3:0] q
);

    // Ring counter logic
    always @(posedge clk or posedge reset) begin
        if (reset)
            q <= 4'b0001;
        else
            q <= {q[2:0], q[3]}; // Shift left and wrap MSB to LSB
    end

endmodule

