module top_module(
    input [1:0] clks,
    input c0,
    input c1,
    input check,
    output reg o_check
);reg [1:0] state;
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

    always @(posedge clks[1] or posedge clks[0]) begin
        case(state)
            S0: begin
                if(c0 && !c1)
                    state <= S1;
                else if(!c0 && c1)
                    state <= S2;
            end
            S1: begin
                if(c0 && !c1)
                    state <= S3;
                else if(!c0 && !c1)
                    state <= S0;
            end
            S2: begin
                if(!c0 && c1)
                    state <= S3;
                else if(c0 && !c1)
                    state <= S0;
            end
            S3: begin
                if(!c0 && !c1)
                    state <= S2;
                else if(c0 && c1)
                    state <= S1;
            end
        endcase
    end

    always @(posedge clks[1] or posedge clks[0]) begin
        if(state == S3 && check)
            o_check <= 1;
        else
            o_check <= 0;
    end

    initial state <= S0;

endmodule

module mux_2to1 (
    input [7:0] in0,
    input [7:0] in1,
    input sel,
    output reg [7:0] out
);always_comb begin
        case (sel)
            1'b0: out = in0;
            1'b1: out = in1;
            default: out = 8'b00000000;
        endcase
    end

endmodule

