module top_module(
  input in,
  output out
);parameter vth = 50; // threshold voltage level (% of vdd)
parameter vdd = 3.3; // supply voltage level (V)

reg out_reg;
wire rising_threshold;
wire falling_threshold;

assign rising_threshold = vdd * vth / 100;
assign falling_threshold = vdd * (100 - vth) / 100;

always @(in) begin
  if (in > rising_threshold) begin
    out_reg <= 1'b1;
  end else if (in < falling_threshold) begin
    out_reg <= 1'b0;
  end
end

assign out = out_reg;

endmodule

