module top_module( clk,
                            reset,
                            cout,
                            initial_value,
                            modulus,
                            time_delay);// INPUT PORTS
    input clk;
    input reset;
    input [31:0] initial_value;
    input [31:0] modulus;
    input [31:0] time_delay;

    // OUTPUT PORTS
    output cout;

    // INTERNAL VARIABLES AND NETS
    reg [31:0] count;
    reg tmp_cout;
    reg first_rising_edge;
    reg clk_last_value;
    reg cout_tmp;

    initial
    begin
        count = initial_value;
        first_rising_edge = 1;
        clk_last_value = 0;
    end

    always @(posedge clk or posedge reset)
    begin
        if (reset)
        begin
            count <= initial_value;
            tmp_cout <= 0;
            first_rising_edge <= 1;
            cout_tmp <= tmp_cout;
        end
        else begin
            if (first_rising_edge)
            begin
                first_rising_edge <= 0;
                tmp_cout <= 1'b0;
                cout_tmp <= #(time_delay) tmp_cout;
            end
            else if (count < modulus-1)
            begin
                count <= count + 1;
                tmp_cout <= 1'b0;
                cout_tmp <= #(time_delay) tmp_cout;
            end
            else
            begin
                count <= initial_value;
                tmp_cout <= 1'b1;
                cout_tmp <= #(time_delay) tmp_cout;
            end
        end
        clk_last_value <= clk;
    end

    assign cout = cout_tmp;

endmodule

