module top_module(
Cfg_in,
Clk,
Resetn,
NSEL,
DAC,
RE
);input Cfg_in, Clk, Resetn;

output reg[4:0] NSEL;
output reg [3:0] DAC;
output reg RE;

reg [9:0] out; 
reg [4:0] count;

wire strobe;


always @(posedge Clk, negedge Resetn)
begin
    if (Resetn == 0) begin
        out <= 0;
        count <= 10;
    end else begin


        out[9] <= Cfg_in;
        out[8] <= out[9];
        out[7] <= out[8];
        out[6] <= out[7];
        out[5] <= out[6];
        out[4] <= out[5];
        out[3] <= out[4];
        out[2] <= out[3];
        out[1] <= out[2];
        out[0] <= out[1];


        count <= count - 1;
    end    
end

assign strobe = (!count) & (~Clk);

always @(posedge strobe, negedge Resetn)
begin
    if (Resetn == 0) begin
        NSEL <= 0;
        DAC <= 0;
        RE <= 0;
    end else begin
		NSEL[4:0] <= out[9:5];
        DAC[3:0] <= out[4:1];        
        RE <= out[0];
    end
end

endmodule

