module top_module (
        input clk,
        input areset,
        input correct_code,
        input lock_timer_done,
        output reg unlocked);parameter Locked = 2'b01, Unlocked = 2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Locked;
		else begin
			case (state)
				Locked: state <= correct_code ? Unlocked : Locked;
				Unlocked: state <= lock_timer_done ? Locked : Unlocked;
			endcase
		end
	end

	assign unlocked = (state == Unlocked);
endmodule

