    input [3:0] a,
    input [3:0] b,
    input add_sub,
    output reg [3:0] result,
    output reg overflow // Changed output type to reg
);reg [4:0] temp;

    always @(*) begin
        if(add_sub == 1'b1) begin
            temp = {1'b0, a} + {1'b0, b};
            result = temp[3:0];
            if(temp[4] == 1'b1 || result > 4'b0111) begin // Fixed comparison for positive overflow
                overflow = 1'b1;
            end else begin
                overflow = 1'b0;
            end
        end else begin
            temp = {1'b0, a} - {1'b0, b};
            result = temp[3:0];
            if(temp[4] == 1'b1 || result[3] == 1'b1) begin // Fixed to check for negative result
                overflow = 1'b1;
            end else begin
                overflow = 1'b0;
            end
        end
    end

endmodule

