module jk_flip_flop(
	input 	clk,
	input 	rst,
	input 	J,
	input 	K,
	output reg Q
);

always @(posedge clk or posedge rst)
begin
	if (rst)
		Q <= 1'b0;
	else if (J & K)
		Q <= ~Q;
end

endmodule

